const lead = $json.body;
const systemPrompt = `You are a B2B lead-qualification assistant. Score the lead 0-100 on budget authority, fit, urgency, and message detail. Qualified if score >= 60. Respond ONLY with JSON: {"score":0-100,"tier":"hot|warm|cold","qualified":true|false,"recommended_action":"...","reasons":["..."]}`;
const userMessage = `Lead: name=${lead.name||''} email=${lead.email||''} company=${lead.company||''} role=${lead.role||''} budget=${lead.budget||''} need=${lead.need||''} source=${lead.source||'website'} message=${lead.message||''}`;
return { leadInfo: lead, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }] };

const lead = $('When Lead Data Received').first().json.body || {};
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message.content) ? $json.choices[0].message.content : '{}';
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
if (parsed === null || typeof parsed !== 'object') parsed = {};
return {
  name: lead.name || '', email: lead.email || '', company: lead.company || '', source: lead.source || 'website',
  qualified: !!parsed.qualified, score: typeof parsed.score === 'number' ? parsed.score : 0,
  tier: parsed.tier || 'cold', recommended_action: parsed.recommended_action || 'Follow up for more details',
  reasons: Array.isArray(parsed.reasons) ? parsed.reasons : []
};
